/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  logic [7:0] A;
  wire [15:0] B;
  TopModule dut(.A(A), .B(B));
  initial begin
    foreach (A) begin end
    for (int i = 0; i < 256; i++) begin
      A = i[7:0];
      #1;
      if (B "'!== (A * 16'"'h00FB)) begin
        "'$display("MISMATCH A=%0d (0x%0h) B=%0d (0x%0h) expected=%0d (0x%0h)", A, A, B, B, (A*16'"'h00FB), (A*16'h00FB));
        "'$finish;
      end
    end
    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

